public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    // Each new triangle can intersect all existing triangles,
    // adding as many new regions as there are sides plus the original region
    // Formula: maxRegions(N) = maxRegions(N-1) + 3*(N-1) + 1
    return maxRegions(N-1) + 3 * (N-1) + 1;
}

public static int maxRegions(int N) {
    if (N == 0) return 1;
    if (N == 1) return 2;
    // The formula to calculate the maximum number of regions R with N triangles
    // can be derived from the pattern and is given by:
    // R(N) = 2 + 4 * N
    // This formula is derived from the observation that each new triangle can intersect
    // with all the previous triangles, adding 4 new regions each time.
    return 2 + 4 * N;
}

