public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a graph representation using adjacency list
    Map<Integer, List<Integer>> adjacencyList = new HashMap<>();
    for (int i = 0; i < n; i++) {
        adjacencyList.put(i, new ArrayList<>());
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        adjacencyList.get(path[0]).add(path[1]);
        adjacencyList.get(path[1]).add(path[0]);
    }

    // BFS to check if there is a path from start to end
    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visited = new HashSet<>();
    queue.add(start[0] * n + start[1]);
    visited.add(start[0] * n + start[1]);

    int endNode = end[0] * n + end[1];

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        if (currentNode == endNode) {
            return "can be travelled";
        }

        int currentX = currentNode / n;
        int currentY = currentNode % n;

        // Explore neighbors
        int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] direction : directions) {
            int newX = currentX + direction[0];
            int newY = currentY + direction[1];
            int neighborNode = newX * n + newY;

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && adjacencyList.get(currentNode).contains(neighborNode) && !visited.contains(neighborNode)) {
                queue.add(neighborNode);
                visited.add(neighborNode);
            }
        }
    }

    return "cannot be travelled";
}

