public static String appx(String word1, String word2) {
    int commonCount = 0;
    int lengthSum = word1.length() + word2.length();

    if (lengthSum == 0) return "appx(" + word1 + ", " + word2 + ") = 0";

    boolean[] used = new boolean[word2.length()];
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (!used[j] && word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                used[j] = true;
                break;
            }
        }
    }

    int gcd = gcd(commonCount, lengthSum);
    String result = gcd != 1 ? commonCount / gcd + "/" + lengthSum / gcd : commonCount + "";

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

public static String appx(String word1, String word2) {
    // Convert both words to uppercase to ensure case-insensitivity
    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    // Use a set to find common letters
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }

    Set<Character> commonLetters = new HashSet<>();
    for (char c : word2.toCharArray()) {
        if (set1.contains(c)) {
            commonLetters.add(c);
        }
    }

    // Count the number of common letters
    int commonCount = commonLetters.size();

    // Calculate the sum of the lengths of the two words
    int totalLength = word1.length() + word2.length();

    // Find the greatest common divisor (GCD) of commonCount and totalLength
    int gcd = gcd(commonCount, totalLength);

    // Reduce the fraction by dividing by the GCD
    int numerator = commonCount / gcd;
    int denominator = totalLength / gcd;

    // Return the result as a string
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + (denominator == 1 ? "" : "/" + denominator);
}

