public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int n = s.length();

    while (result.length() < n) {
        // Pick characters in ascending order
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }

        // Pick characters in descending order
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
            }
        }
    }

    return result.toString();
}

public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Forward pass
        for (int i = 0; i < 26; i++) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
                remaining--;
            }
        }

        // Backward pass
        for (int i = 25; i >= 0; i--) {
            if (count[i] > 0) {
                result.append((char) (i + 'a'));
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

