    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i / 2, n - i + j); j >= 1; j--) {
            for (int k = num; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - num];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[n][i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

