public int minInsertions(String s) {
    int open = 0; // To count the number of open parentheses needed
    int insertions = 0; // To count the number of insertions made

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++; // Increment open count for an open parenthesis
        } else {
            // If we encounter a closing parenthesis
            if (open > 0) {
                open--; // Match it with an open parenthesis if available
            } else {
                insertions++; // Otherwise, insert a matching open parenthesis
            }
            // Check for a pair of closing parentheses
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next closing parenthesis as it's matched
            } else {
                insertions++; // Insert a matching closing parenthesis
            }
        }
    }

    // Add any remaining open parentheses needed
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int left = 0; // number of '(' needed
    int right = 0; // number of ')' needed
    for (char c : s.toCharArray()) {
        if (c == '(') {
            right += 2; // each '(' needs two ')'
            if (right % 2 == 1) { // if there is an odd ')'
                left++; // need to add a '('
                right--; // and now we need one less ')' as it pairs with the added '('
            }
        } else {
            right--; // got a ')'
            if (right == -1) { // more ')' than '('
                left++; // need to add a '('
                right = 1; // and now we need one ')'
            }
        }
    }
    return left + right; // the number of insertions needed is the sum of '(' and ')'
}

public int minInsertions(String s) {
    int leftNeeded = 0; // To count the number of '(' needed
    int rightNeeded = 0; // To count the number of ')' needed
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            // If we encounter '(', we need two ')' to balance it
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                // If the next character is ')', we can balance one '('
                i += 2; // Move two steps forward
            } else {
                // If the next character is not ')', we need one ')'
                rightNeeded++;
                i += 1; // Move one step forward
            }
        } else {
            // If we encounter ')', we need one '(' to balance it
            leftNeeded++;
            i += 1; // Move one step forward
            // If the next character is also ')', we can balance one '('
            if (i < s.length() && s.charAt(i) == ')') {
                i += 1; // Move one step forward
                leftNeeded--; // One '(' is balanced
            }
        }
    }

    // The result is the sum of leftNeeded and rightNeeded
    return leftNeeded + rightNeeded;
}

