    for (char c : s.toCharArray()) {
        if (c == '(') {
            right += 2; // Each '(' needs two ')' to balance
            if (right % 2 == 1) {
                // If we need an odd number of ')', it means we need to insert one ')' here to make it even
                left++;
                right--;
            }
        } else {
            right--; // Each ')' balances one ')'
            if (right == -1) {
                // If we have more ')' than needed, we need to insert one '(' to balance
                left++;
                right = 1; // We now need one more ')' to balance the inserted '('
            }
        }
    }

    return left + right; // The total number of insertions needed
}

