                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n / 2; i++) {
        operations += n - 2 * i - 1;
    }
    return operations;
}

public int minOperations(int n) {
    int mid = n / 2;
    int last = (2 * (n - 1)) + 1;
    int first = 1;
    int operations = 0;

    if (n % 2 == 0) {
        for (int i = 0; i < mid; i++) {
            operations += (last - first) / 2;
            first += 2;
            last -= 2;
        }
    } else {
        for (int i = 0; i < mid; i++) {
            operations += (last - first) / 2;
            first += 2;
            last -= 2;
        }
    }

    return operations;
}

