public int findMinFibonacciNumbers(int k) {
    if (k <= 2) return 1;
    int a = 1, b = 1;
    while (b <= k) {
        int t = b;
        b += a;
        a = t;
    }
    return 1 + findMinFibonacciNumbers(k - a);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    int a = 1, b = 1;
    while (b <= k) {
        int temp = a + b;
        a = b;
        b = temp;
    }
    return 1 + findMinFibonacciNumbers(k - a);
}

public int findMinFibonacciNumbers(int k) {
    if (k < 1) return 0;

    int a = 1, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    return 1 + findMinFibonacciNumbers(k - a);
}

