public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate all Fibonacci numbers less than or equal to k
    int a = 0, b = 1;
    while (b <= k) {
        int temp = b;
        b = a + b;
        a = temp;
    }

    // Now 'a' is the largest Fibonacci number less than or equal to k
    // Subtract 'a' from k and recurse
    return 1 + findMinFibonacciNumbers(k - a);
}

