public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        // Start with 'a' which contributes 1 to the value
        result.append('a');
    }
    // Start adding to the last character to maximize the value incrementally
    k -= n;
    int i = n - 1;
    while (k > 0) {
        // Calculate how much we can add to the current character
        int add = Math.min(25, k); // We can add at most 25 to change 'a' to 'z'
        result.setCharAt(i, (char)('a' + add));
        k -= add;
        i--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remainingValue = k - n; // Initial value assuming all characters are 'a'

    for (int i = 0; i < n; i++) {
        if (remainingValue > 25) {
            result.append('z');
            remainingValue -= 25; // Append 'z' and reduce remaining value by 25
        } else {
            result.append((char) ('a' + remainingValue));
            remainingValue = 0; // Current character fully accounts for the remaining value
            break;
        }
    }

    // Fill the remaining length with 'a'
    while (result.length() < n) {
        result.append('a');
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    while (n > 0) {
        int res = k - 26 * (n - 1);
        if (res <= 0) {
            result.append('a');
            k -= 1;
        } else {
            result.append((char)('a' + res - 1));
            k -= res;
        }
        n--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    while (n > 0) {
        int remaining = k - n + 1;
        if (remaining <= 26) {
            result.append((char) ('a' + remaining - 1));
            k -= remaining;
        } else {
            result.append('z');
            k -= 26;
        }
        n--;
    }
    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < n; i++) {
        result.append('a');
    }
    k -= n;
    while (k > 0) {
        int idx = result.length() - 1;
        while (idx >= 0 && k > 0) {
            int add = Math.min(25, k);
            char newChar = (char) (result.charAt(idx) + add);
            result.setCharAt(idx, newChar);
            k -= add;
            idx--;
        }
    }
    return result.toString();
}

