public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int n = heights.length;
    int[] stack = new int[n];
    int top = -1;

    for (int i = 0; i < n; i++) {
        while (top != -1 && heights[i] < heights[stack[top]]) {
            int height = heights[stack[top]];
            top--;
            int left = top == -1 ? -1 : stack[top];
            maxArea = Math.max(maxArea, (i - 1 - left) * height);
        }
        stack[++top] = i;
    }

    while (top != -1) {
        int height = heights[stack[top]];
        top--;
        int left = top == -1 ? -1 : stack[top];
        maxArea = Math.max(maxArea, (n - 1 - left) * height);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Fill left array where left[i] is the index of the first bar on the left 
    // that is smaller than heights[i]
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j];
        }
        left[i] = j;
    }

    // Fill right array where right[i] is the index of the first bar on the right 
    // that is smaller than heights[i]
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j];
        }
        right[i] = j;
    }

    // Calculate the maximum area of rectangle with heights[i]
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = right[i] - left[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int maxArea = 0;
    int[] stack = new int[heights.length];
    int top = -1;
    int i = 0;

    while (i < heights.length) {
        if (top == -1 || heights[stack[top]] <= heights[i]) {
            stack[++top] = i++;
        } else {
            int h = heights[stack[top--]];
            int width = top == -1 ? i : i - stack[top] - 1;
            maxArea = Math.max(maxArea, h * width);
        }
    }

    while (top != -1) {
        int h = heights[stack[top--]];
        int width = top == -1 ? i : i - stack[top] - 1;
        maxArea = Math.max(maxArea, h * width);
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] lessFromLeft = new int[n];
    int[] lessFromRight = new int[n];

    lessFromRight[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) {
            p = lessFromRight[p];
        }
        lessFromRight[i] = p;
    }

    lessFromLeft[0] = -1;
    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) {
            p = lessFromLeft[p];
        }
        lessFromLeft[i] = p;
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (lessFromRight[i] - lessFromLeft[i] - 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Fill left array with the closest shorter bars to the left
    for (int i = 0; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = left[j] - 1;
        }
        left[i] = j + 1;
    }

    // Fill right array with the closest shorter bars to the right
    for (int i = n - 1; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = right[j] + 1;
        }
        right[i] = j - 1;
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] + 1));
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 0;
    int[][] dirs = {{-1, 1}, {1, -1}};

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[r][c];
        r += dirs[d][0];
        c += dirs[d][1];

        if (r >= 0 && c >= 0 && r < rows && c < cols) continue;

        if (d == 0) {
            if (c == cols) { r++; c--; }
            else if (r < 0) r++;
        } else {
            if (r == rows) { c++; r--; }
            else if (c < 0) c++;
        }
        d = 1 - d;
    }

    return result;
}

