public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Traverse the array from right to left and find the first
    // digit that is smaller than the digit next to it.
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, then all digits are in descending order
    // and no larger permutation is possible.
    if (i == -1) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of (i-th digit)
    // which is greater than digits[i]
    int x = digits[i];
    int smallest = i + 1;
    for (int j = i + 2; j < len; j++) {
        if (digits[j] > x && digits[j] < digits[smallest]) {
            smallest = j;
        }
    }

    // Step 3: Swap the above found smallest digit with digits[i]
    char temp = digits[i];
    digits[i] = digits[smallest];
    digits[smallest] = temp;

    // Step 4: Sort the digits after (i-th digit) in ascending order
    java.util.Arrays.sort(digits, i + 1, len);

    // Convert the array of characters back to an integer
    long result = Long.parseLong(new String(digits));
    return (result > Integer.MAX_VALUE) ? -1 : (int) result;
}

