public static boolean isBoomerang(int[][] points) {
    int dx = points[1][0] - points[0][0];
    int dy = points[1][1] - points[0][1];
    int ex = points[2][0] - points[0][0];
    int ey = points[2][1] - points[0][1];
    return dx * ey != dy * ex;
}

public static boolean isBoomerang(int[][] points) {
    // Calculate the vectors for the two segments of the triangle formed by the points
    int dx1 = points[1][0] - points[0][0];
    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    // Calculate the cross product of the two vectors
    int crossProduct = dx1 * dy2 - dx2 * dy1;

    // If the cross product is zero, the points are collinear and do not form a boomerang
    return crossProduct != 0;
}

